import { Router, type ErrorRequestHandler } from 'express';
import { z } from 'zod';
import { findHub, requestHub } from '../library/HubClient';
import { currentLibraryRoot } from '../services/ProjectLibrary';
import { getConfigManager } from '../services/ConfigManager';
import { ReferenceDiscoveryRequestSchema } from '../types/reference-connectors';
import {
  ReferenceApprovalSchema,
  ReferencePlanRequestSchema,
} from '../types/reference-onboarding';
import {
  ProfileRuntimeSchema,
  type ProfileProvider,
} from '../types/design-profile';
import {
  DesignLibrarySnapshotSchema,
  designLibraryEntryPath,
} from '../types/design-library';
import type { DesignLibraryEntriesResponse } from '../types/api-responses';
import { libraryPageUrl } from '../library/browserLaunch';
import { errorMessage } from '../utils/errorMessage';

const LINKED_ENTRY_PROVIDERS: ReadonlySet<ProfileProvider> = new Set([
  'image',
  'arena',
  'cosmos',
]);
const MAX_ENTRY_LOOKUPS = 100;
const MAX_REFERENCE_ID_LENGTH = 200;

const LibraryEntriesQuerySchema = z.object({
  referenceId: z
    .union([z.string(), z.array(z.string())])
    .transform((value) => [value].flat())
    .pipe(
      z
        .array(z.string().min(1).max(MAX_REFERENCE_ID_LENGTH))
        .min(1)
        .max(MAX_ENTRY_LOOKUPS),
    ),
});

const connectedHub = async () => {
  if (!getConfigManager().isAuthenticated())
    throw new Error('Sign in to Rivet to connect design references');
  const hub = await findHub(currentLibraryRoot());
  if (!hub)
    throw new Error('Run rivet open to reconnect to the design library');
  return hub;
};

export const createReferenceProfilesRouter = () => {
  const router = Router();

  router.get('/reference-profiles', async (_req, res) => {
    res.json(
      await requestHub({
        hub: await connectedHub(),
        endpoint: '/profile',
        method: 'GET',
      }),
    );
  });

  router.get('/reference-profiles/library-entries', async (req, res) => {
    const referenceIds = new Set(
      LibraryEntriesQuerySchema.parse(req.query).referenceId,
    );
    const hub = getConfigManager().isAuthenticated()
      ? await findHub(currentLibraryRoot())
      : null;
    if (!hub) {
      res.json({ entries: [] } satisfies DesignLibraryEntriesResponse);
      return;
    }
    const library = DesignLibrarySnapshotSchema.parse(
      await requestHub({ hub, endpoint: '/profile/library', method: 'GET' }),
    );
    res.json({
      entries: library.references
        .filter(
          (reference) =>
            referenceIds.has(reference.id) &&
            LINKED_ENTRY_PROVIDERS.has(reference.provider) &&
            reference.media.length > 0,
        )
        .map((reference) => ({
          referenceId: reference.id,
          url: libraryPageUrl({
            hub,
            path: designLibraryEntryPath(reference.id),
          }).toString(),
        })),
    } satisfies DesignLibraryEntriesResponse);
  });

  router.post('/reference-profiles/discoveries', async (req, res) => {
    const input = ReferenceDiscoveryRequestSchema.parse(req.body);
    res.status(201).json(
      await requestHub({
        hub: await connectedHub(),
        endpoint: '/profile/discoveries',
        body: input,
      }),
    );
  });

  router.post('/reference-profiles/import-plans', async (req, res) => {
    const input = ReferencePlanRequestSchema.parse(req.body);
    res.status(201).json(
      await requestHub({
        hub: await connectedHub(),
        endpoint: '/profile/import-plans',
        body: input,
      }),
    );
  });

  router.post(
    '/reference-profiles/import-plans/:id/imports',
    async (req, res) => {
      const input = ReferenceApprovalSchema.parse({
        ...req.body,
        id: req.params.id,
      });
      res.status(202).json(
        await requestHub({
          hub: await connectedHub(),
          endpoint: `/profile/import-plans/${input.id}/imports`,
          body: { revision: input.revision, isApproved: true },
        }),
      );
    },
  );

  router.patch('/reference-profiles', async (req, res) => {
    const input = z
      .union([
        z
          .object({ isEnabled: z.literal(true), runtime: ProfileRuntimeSchema })
          .strict(),
        z.object({ autonomousReferences: z.boolean() }).strict(),
      ])
      .parse(req.body);
    res.status('isEnabled' in input ? 202 : 200).json(
      await requestHub({
        hub: await connectedHub(),
        endpoint: '/profile',
        method: 'PATCH',
        body: input,
      }),
    );
  });

  const handleError: ErrorRequestHandler = (
    error: unknown,
    _req,
    res,
    _next,
  ) => {
    res.status(error instanceof z.ZodError ? 400 : 502).json({
      error: errorMessage(error, 'Reference profile request failed'),
    });
  };
  router.use(handleError);

  return router;
};
